"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[72049],{72049:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/closed-room-murder-game_1.png\\"\\n          title=\\"The Locked Room Murder Game\\"\\n          author=\\"Shogo Utano\\"\\n          publisher=\\"Hans Media\\"\\n          publishedDate=\\"2022-08-31\\"\\n          isbn=\\"9791160076141\\"\\n          rating=3\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\nFive anonymous people gather on the internet to play a murder mystery game.  \\nEach person takes a turn as the culprit and presents a murder case as a problem, while the others solve it.  \\nBut the murder case problem is not a fictional problem, but an actual murder case committed by the person playing the role of the culprit.  \\n<br>\\nThis concept is interesting, but there were some forced parts that reduced immersion.  \\nThe situation of not getting caught despite the tricks not being that great, and characters who are good at devising tricks for their own murders but become stupid when inferring others\' cases.  \\n<br>\\nPerhaps because I watched it with too much expectation, the disappointment was quite large.  "}')}}]);